const A = 'https://api.asaas.com/v3';
// Motivo legível de um erro do Asaas (o n8n põe a resposta dentro de error.message).
const motivo = (r) => {
  const m = String((r && r.error && (r.error.description || r.error.message)) || 'erro desconhecido');
  const d = m.match(/"description"\s*:\s*"([^"]+)"/);
  return (d ? d[1] : m).slice(0, 200);
};
const e = $input.first().json || {};
const valida = (c) => c === 'CNPJ 1' || c === 'CNPJ 2';
const destino = valida(e.destino) ? e.destino : 'CNPJ 1';
const idAtual = String(e.idAtual || '').trim();
// Cliente com Asaas mas sem a conta anotada: é do tempo de uma conta só (CNPJ 1).
const de = idAtual ? (valida(e.contaAtual) ? e.contaAtual : 'CNPJ 1') : '';
let acao = 'criar';
if (!e.entidadeId || !e.payload || typeof e.payload !== 'object') acao = 'nada';
else if (idAtual && de === destino) acao = 'atualizar';
else if (idAtual) acao = 'mover';
return [{ json: { entidadeId: e.entidadeId || '', payload: e.payload || {}, destino, de, idAtual, acao } }];

