// Tirar o cliente de um Asaas apaga junto as cobranças pendentes/vencidas e as assinaturas:
// antes de mover, confere que não há nenhuma.
const d = $('Decide').first().json;
const c = encodeURIComponent(d.idAtual);
return [
  { json: { conta: d.de, metodo: 'GET', url: A + '/payments?customer=' + c + '&status=PENDING&limit=1' } },
  { json: { conta: d.de, metodo: 'GET', url: A + '/payments?customer=' + c + '&status=OVERDUE&limit=1' } },
  { json: { conta: d.de, metodo: 'GET', url: A + '/subscriptions?customer=' + c + '&status=ACTIVE&limit=1' } },
];

const rs = $input.all().map((i) => i.json || {});
const falhou = rs.length !== 3 || rs.some((r) => r.error || r.pulado);
const abertas = rs.some((r) => !r.error && ((Number(r.totalCount) || 0) > 0 || (Array.isArray(r.data) && r.data.length > 0)));
return [{ json: { livre: !falhou && !abertas, abertas, falhou } }];

const d = $('Decide').first().json;
const p = $input.first().json || {};
const aviso = p.abertas
  ? 'Este cliente tem cobrança em aberto no Asaas do ' + d.de + ', por isso continua lá por enquanto (tirar de lá apagaria a cobrança). Depois que ela for paga ou cancelada, é só salvar o cliente de novo.'
  : 'Não consegui conferir as cobranças no Asaas do ' + d.de + '; o cliente continua lá. Tente salvar de novo daqui a pouco.';
return [{ json: { ok: false, acao: 'mover', id: d.idAtual, conta: d.de, info: '', aviso } }];

