const A = 'https://api.asaas.com/v3';
// Motivo legível de um erro do Asaas (o n8n põe a resposta dentro de error.message).
const motivo = (r) => {
  const m = String((r && r.error && (r.error.description || r.error.message)) || 'erro desconhecido');
  const d = m.match(/"description"\s*:\s*"([^"]+)"/);
  return (d ? d[1] : m).slice(0, 200);
};
// Se o cliente já existe no Asaas de destino (mesmo CPF/CNPJ), reaproveita em vez de duplicar.
const d = $('Decide').first().json;
const r = $input.first().json || {};
if (r.error) return [{ json: { pular: true, motivoBusca: motivo(r) } }];
const lista = Array.isArray(r.data) ? r.data.filter((c) => c && c.id && !c.deleted) : [];
const achado = lista.find((c) => c.externalReference === d.entidadeId) || lista[0] || null;
// Mesmas regras de sempre ao entrar no Asaas: notificações desligadas para o cliente.
const corpo = { ...d.payload, notificationDisabled: true, externalReference: d.entidadeId };
return [{ json: achado
  ? { conta: d.destino, metodo: 'PUT', url: A + '/customers/' + encodeURIComponent(achado.id), corpo, reaproveitado: true }
  : { conta: d.destino, metodo: 'POST', url: A + '/customers', corpo } }];

