const novoId = p.pular ? '' : String(r.id || '');
const erro = p.pular ? p.motivoBusca : (novoId ? '' : motivo(r));
return [{ json: { conta: d.destino, metodo: 'GET', url: A + '/customers/' + encodeURIComponent(novoId) + '/notifications', pular: !novoId, novoId, erro } }];

// Mesmo padrão de notificações de sempre (só e-mail nos eventos de cobrança; o cliente
// fica com notificationDisabled, então nada sai enquanto o dono não ligar no Asaas).
const DESEJADO = [{"event":"PAYMENT_CREATED","offset":0,"email":true,"sms":false,"whatsapp":false,"ligacao":false},{"event":"PAYMENT_UPDATED","offset":0,"email":false,"sms":false,"whatsapp":false,"ligacao":false},{"event":"PAYMENT_DUEDATE_WARNING","offset":10,"email":true,"sms":false,"whatsapp":false,"ligacao":false},{"event":"PAYMENT_DUEDATE_WARNING","offset":0,"email":false,"sms":false,"whatsapp":false,"ligacao":false},{"event":"SEND_LINHA_DIGITAVEL","offset":0,"email":false,"sms":false,"whatsapp":false,"ligacao":false},{"event":"PAYMENT_OVERDUE","offset":0,"email":true,"sms":false,"whatsapp":false,"ligacao":false},{"event":"PAYMENT_OVERDUE","offset":7,"email":true,"sms":false,"whatsapp":false,"ligacao":false},{"event":"PAYMENT_RECEIVED","offset":0,"email":false,"sms":false,"whatsapp":false,"ligacao":false}];
const n = $('Pede notificacoes').first().json;
if (!n.novoId) return [{ json: { pular: true } }];
const lista = ($input.first().json || {}).data || [];
const itens = [];
for (const alvo of DESEJADO) {
  const atual = lista.find((x) => x.event === alvo.event && x.scheduleOffset === alvo.offset);
  if (!atual) continue;
  itens.push({ json: { conta: n.conta, metodo: 'PUT', url: 'https://api.asaas.com/v3/notifications/' + encodeURIComponent(atual.id), corpo: {
    emailEnabledForCustomer: alvo.email, smsEnabledForCustomer: alvo.sms,
    whatsappEnabledForCustomer: alvo.whatsapp, phoneCallEnabledForCustomer: alvo.ligacao,
  } } });
}
return itens.length ? itens : [{ json: { pular: true } }];

