    aviso: erro ? 'Não consegui tirar o cliente do Asaas do ' + d.de + ' (' + erro + '); tire de lá à mão.' : '' } }];
}
return [{ json: { ok: true, acao: 'criar', id: n.novoId, conta: d.destino, info: '', aviso: '' } }];
